/// Запись подхода живого уровня к цене (F1 этапа F): момент, когда лучшая
/// цена **другой** стороны впервые вошла в полосу `D` bps от уровня, живой
/// уровень при этом держал порог В-66 и был не лучшим (то есть цена ещё не
/// дошла). Запись эмитится **на снятии**: касанием, смертью уровня или
/// уходом цены за `2 × D` (гистерезис). Поля, кроме `disarm_*`, — состояние
/// кадра взвода; уровень жив и в `LevelRecord` не попадает ничем.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ApproachRecord {
    /// Сторона книги — сторона уровня (вход ставится за неё).
    pub side: Side,
    /// Цена уровня в тиках.
    pub price_tick: i64,
    /// Порядковый номер подхода у этого уровня: 0, 1, 2… (растёт как
    /// `touch_index`, включая подходы уровней прогрева — те не эмитируются).
    pub approach_index: u32,
    /// Кадр взвода, мс.
    pub arm_ms: i64,
    /// Расстояние от уровня до лучшей цены другой стороны в кадре взвода,
    /// bps по цене уровня (тот же расчёт, что `dist_bps` ёмкости).
    pub arm_dist_bps: i64,
    /// Кадр рождения уровня, мс: возраст на взводе — `arm_ms − level_birth_ms`.
    pub level_birth_ms: i64,
    /// Размер уровня в лотах в кадре взвода.
    pub size_at_arm: i64,
    /// Лучшая цена **своей** стороны в кадре взвода (у бид-стены — лучший
    /// бид, он выше цены стены: цена к стене ещё не дошла).
    pub best_own_tick: i64,
    /// Лучшая цена **другой** стороны на её последнем кадре к моменту взвода
    /// (у бид-стены — лучший аск) — от неё считается полоса.
    pub best_opp_tick: i64,
    /// Оборот инструмента за последний час к взводу, лоты (как у касания).
    pub flow_1h_lots: i64,
    /// Сила «×соседи» на кадре взвода для окон `STRENGTH_WINDOWS_BPS`,
    /// проценты × 100; `-1` — соседей в окне не было (как у касания).
    pub strength_e2: [i64; STRENGTH_WINDOWS_BPS.len()],
    /// Направленная глубина на кадре взвода (см. `TouchRecord::depth_behind_lots`,
    /// T2 П-02): та же сумма, тот же прокси на `.50` против `.200`.
    pub depth_behind_lots: i64,
    /// «Завал» на кадре взвода (T-28, Г-28 П-02 на подходе): то же правило, что
    /// `TouchRecord::stack_levels` (живые уровни той же стороны не ниже `H3` не
    /// дальше `DISTANCE_MAX_BPS`, включая сам уровень, после свипа кадра), но на
    /// кадре взвода, а не старта касания.
    pub stack_levels_at_arm: u32,
    /// Лоты впереди уровня к взводу (T-28): то же правило, что
    /// `TouchRecord::frontrun_lots` (В-45, кадр не позже секунды до), от метки
    /// взвода. На взводе цена ещё в полосе от стены — это всё, что стоит между
    /// стеной и ценой, больше фронтрана касания.
    pub frontrun_lots_at_arm: i64,
    /// Кадр начала касания, если подход кончился касанием.
    pub touch_start_ms: Option<i64>,
    /// Кадр снятия подхода (касание, смерть уровня или уход цены).
    pub disarm_ms: i64,
    /// Чем подход кончился.
    pub disarm_reason: ApproachEnd,
}

impl ApproachRecord {
    /// Возраст уровня на момент взвода, мс (`touch_record.age_ms` подхода).
    pub fn age_ms(&self) -> i64 {
        self.arm_ms - self.level_birth_ms
    }

    /// Сколько подход жил: от взвода до снятия, мс.
    pub fn duration_ms(&self) -> i64 {
        self.disarm_ms - self.arm_ms
    }
}

/// Потолок счётчика `round_zeros`: «3+» — практики называют круглым и
    start_ms: i64,
    first_lots: i64,
    /// Цена **ближайшего** уровня с ненулевым размером строго лучше нашего,
    /// на том же наблюдении, что `first_lots` (B2, 2026-09-17). Именно она —
    /// «первый фронтранер»: вход от фронтрана (спека §2) ставится на его цену,
    /// а не на «лучшую из всех» — иначе вход уезжал бы к середине.
    first_tick: Option<i64>,
    last_ms: i64,
    last_lots: i64,
    last_tick: Option<i64>,
}

impl FrontrunSlot {
    fn new(ts_ms: i64, lots: i64, tick: Option<i64>) -> Self {
        Self {
            start_ms: ts_ms,
            first_lots: lots,
            first_tick: tick,
            last_ms: ts_ms,
            last_lots: lots,
            last_tick: tick,
        }
    }
}

/// Состояние идущего касания — целые в `Live`, кучи нет.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Touch {
    start_ms: i64,
    /// Номер кадра начала: `stack` заполняется после свипа того же кадра, и
    /// сравнение по номеру кадра, а не по метке (несколько кадров могут
    /// делить миллисекунду), говорит, что заполнять пора.
    start_frame: u64,
    size_at: i64,
    size_max_before: i64,
    frontrun: i64,
    /// Цена того же наблюдения фронтрана (B2): из неё строится вход «от
    /// первого фронтранера»; `None` — фронтрана не было вовсе.
    frontrun_tick: Option<i64>,
    swept: i64,
    /// Окно «завала» в тиках — `stack_window_ticks` цены уровня, один раз
    /// на старте.
    window_ticks: i64,
    traded_at_start: i64,
    stack: u32,
    /// Вторая плотность завала (см. `TouchRecord::stack_next_tick`).
    stack_next_tick: Option<i64>,
    /// Объём против уровня за первые окна `REACTION_WINDOWS_S` касания —
    /// копится в `observe_trade` по метке исполнения.
    traded_first_s: [i64; REACTION_WINDOWS_S.len()],
    /// Оборот инструмента за час к старту (см. `TouchRecord::flow_1h_lots`).
    flow_1h_lots: i64,
    /// Уровень в этом кадре перестал быть лучшей ценой: конец касания ждёт
    /// свипа — смерть в том же кадре имеет приоритет.
    end_pending: bool,
    /// Сила «×соседи» на кадре старта (см. `TouchRecord::strength_e2`).
    strength_e2: [i64; STRENGTH_WINDOWS_BPS.len()],
    /// Минимум силы за окна `STRENGTH_HELD_WINDOWS_S` (см. `TouchRecord`).
    strength_held_e2: [i64; STRENGTH_HELD_WINDOWS_S.len()],
    /// Прошлых рождений уровня на этой цене в окне `repeat_window_ms`.
    repeat_count: u32,
    /// Направленная глубина на кадре старта (см. `TouchRecord::depth_behind_lots`).
    depth_behind_lots: i64,
}

/// Взведённый подход уровня — целые в `Live`, кучи нет (F1). Поля — состояние
/// кадра взвода; из них собирается `ApproachRecord` на снятии.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Approach {
    arm_ms: i64,
    arm_dist_bps: i64,
    size_at_arm: i64,
    best_own_tick: i64,
    best_opp_tick: i64,
    flow_1h_lots: i64,
    strength_e2: [i64; STRENGTH_WINDOWS_BPS.len()],
    /// Направленная глубина на кадре взвода (см. `TouchRecord::depth_behind_lots`,
    /// T2 П-02).
    depth_behind_lots: i64,
    /// Лоты впереди уровня к взводу (`ApproachRecord::frontrun_lots_at_arm`).
    frontrun_lots: i64,
    /// «Завал» на кадре взвода — ставится после свипа кадра (`compute_arm_stacks`).
    stack_levels: u32,
}

/// Один кадр уровня для правила взвода/снятия подхода (F1): всё, что нужно
/// `observe_approach`, — чтобы правило читалось отдельно от горячего цикла.
#[derive(Debug, Clone, Copy)]
struct ApproachFrame {
    ts_ms: i64,
    tick: i64,
    size_lots: i64,
    /// Уровень — лучшая цена своей стороны в этом кадре (касание идёт либо
    /// началось).
    best: bool,
    /// Лучшая цена своей стороны в этом кадре.
    best_own_tick: i64,
    /// Лучшая цена другой стороны на её последнем кадре.
    best_opp_tick: i64,
    flow_1h_lots: i64,
    depth_behind_lots: i64,
    /// Лоты впереди уровня за секунду до кадра (`Live::frontrun_before`).
    frontrun_lots: i64,
}

/// Живой уровень: всё состояние — несколько целых, кучи нет.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Live {
    birth_ms: i64,
    /// Возраст перенесён с прошлых суток (`with_carried_births`, аудит дизайна 22.09 Т3):
    /// рождение раньше начала трекера, но уровень наблюдался непрерывно — прогрев его не глушит.
    carried: bool,
    max: i64,
    max_ms: i64,
    prev: i64,
    first_decrease_ms: Option<i64>,
    repeat: u32,
    seen_frame: u64,
    seen_top50: bool,
    seen_size: i64,
    /// Прошёл ли уровень порог силы на последнем наблюдении (у режимов без
    /// силы — всегда `true`).
    seen_strong: bool,
    traded: i64,
    /// RPI-сделки на этой цене: в `traded` не идут, но копятся отдельно —
    /// иначе метка исхода считает чужой объём (В-55).
    rpi: i64,
    /// Сумма лотов строго лучше уровня по цене на последнем кадре, где он
    /// наблюдался, — `swept_lots` будущего касания.
    better_lots: i64,
    /// Слоты выборки фронтрана (В-45): текущая секунда наблюдений и
    /// предыдущая; `None` — уровень моложе одного шага.
    slot_new: FrontrunSlot,
    slot_old: Option<FrontrunSlot>,
    /// Был ли уровень лучшей ценой на последнем наблюдении: касание — переход
    /// `false → true`, не состояние.
    was_best: bool,
    /// Сколько касаний у уровня уже кончилось.
    touch_index: u32,
    touch: Option<Touch>,
    /// Взведённый подход (F1); `None` — не взведён.
    approach: Option<Approach>,
    /// Сколько подходов у уровня уже кончилось (растёт как `touch_index`).
    approach_index: u32,
    /// Лучшая цена другой стороны уходила за `2 × D` после последнего снятия
    /// — уровень может взводиться снова. У новорождённого `true`.
    approach_clear: bool,
    /// Кольцо выборок силы: метки и значения (`e2`, `-1` — не определена).
    sh_ts: [i64; STRENGTH_HIST_SLOTS],
    sh_e2: [i64; STRENGTH_HIST_SLOTS],
    sh_len: u8,
    sh_next: u8,
}

impl Live {
    /// Пора ли писать выборку силы кадра `ts_ms`: с последней прошло не меньше

    let v = i128::from(gap) * BPS_PER_UNIT / i128::from(tick);
    i64::try_from(v).unwrap_or(i64::MAX)
}

/// Запись подхода из состояния уровня и снятого взвода.
fn approach_record(
    key: (u8, i64),
    lv: &Live,
    a: Approach,
    disarm_ms: i64,
    touch_start_ms: Option<i64>,
    reason: ApproachEnd,
) -> ApproachRecord {
    ApproachRecord {
        side: side_of(key),
        price_tick: key.1,
        approach_index: lv.approach_index,
        arm_ms: a.arm_ms,
        arm_dist_bps: a.arm_dist_bps,
        level_birth_ms: lv.birth_ms,
        size_at_arm: a.size_at_arm,
        best_own_tick: a.best_own_tick,
        best_opp_tick: a.best_opp_tick,
        flow_1h_lots: a.flow_1h_lots,
        strength_e2: a.strength_e2,
        depth_behind_lots: a.depth_behind_lots,
        stack_levels_at_arm: a.stack_levels,
        frontrun_lots_at_arm: a.frontrun_lots,
        touch_start_ms,
        disarm_ms,
        disarm_reason: reason,
    }
}

/// Правило взвода и снятия подхода (F1) по одному кадру уровня. `true` — подход
/// взведён в этом кадре («завал» на взводе ставится после свипа, T-28).
///
/// - **Взвод** — уровень жив, не лучший на своей стороне (цена ещё не дошла),
///   держит порог В-66 (`holds`, тот же, что у касания), возраст не меньше
///   `min_age_ms`, лучшая цена другой стороны впервые вошла в полосу `d_bps`
///   (`tick_diff × 10⁴ ≤ d × tick`, целочисленно) и после прошлого снятия
///   цена успела уйти за `2 × d`. Числа `d` и `min_age_ms` — конфигурация
///   замера, не константа кода.
/// - **Снятие**: касание (уровень стал лучшим — это первый такой кадр после
///   взвода), уход цены за `2 × d` (гистерезис: без него цена на границе
///   полосы взводила бы подход каждый кадр), смерть уровня — в свипе
///   (`ApproachEnd::LevelDeath`), здесь не видна.
/// - Записи уровня прогрева считаются (индекс растёт), но не эмитируются
///   (`emit = false`) — как у касаний.
/// - `arm_inputs` — `(holds, strength_e2)` кадра: порог В-66 и сила «×соседи».
///   Нужны только в момент взвода, поэтому зовутся только когда все прочие
///   условия взвода выполнены (Р1, T-17: раньше считались на каждом кадре
///   каждого живого уровня — 2/3 времени `lob touches`, замер
///   `docs/findings/backtest-optimization-2026-09-26.md`). Обе — чистые функции
///   кадра, условия взвода — конъюнкция без побочных эффектов, поэтому решение и
///   записи те же.
fn observe_approach(
    lv: &mut Live,
    cfg: (i64, i64),
    s: u8,
    arm_inputs: impl FnOnce() -> (bool, [i64; STRENGTH_WINDOWS_BPS.len()]),
    f: ApproachFrame,
    emit: bool,
    out: &mut Vec<ApproachRecord>,
) -> bool {
    let (d_bps, min_age_ms) = cfg;
    let key = (s, f.tick);
    // Знаковое расстояние от уровня до чужой лучшей цены: у бида чужая цена
    // выше (положительно), у аска — ниже.
    let gap = if s == side_key(Side::Bid) {
        f.best_opp_tick - f.tick
    } else {
        f.tick - f.best_opp_tick
    };
    let scaled = i128::from(gap) * BPS_PER_UNIT;
    let near = scaled <= i128::from(d_bps) * i128::from(f.tick);
    let far = scaled > i128::from(d_bps.saturating_mul(2)) * i128::from(f.tick);
    if let Some(a) = lv.approach {
        // Касание (уровень стал лучшим) и уход цены — снятие; смерть уровня
        // снимает подход в свипе.
        if f.best || far {
            let (reason, touch_start_ms) = if f.best {
                (ApproachEnd::Touch, Some(f.ts_ms))
            } else {
                (ApproachEnd::PriceLeft, None)
            };
            let rec = approach_record(key, lv, a, f.ts_ms, touch_start_ms, reason);
            lv.approach = None;
            lv.approach_index = lv.approach_index.saturating_add(1);
            if emit {
                out.push(rec);
            }
            // Снова взводиться можно только после ухода цены за `2 × d`:
            // снятие касанием такого ухода не даёт.
            lv.approach_clear = far;
        }
        return false;
    }
    if far {
        lv.approach_clear = true;
    }
    if !near || !lv.approach_clear || f.best {
        return false;
    }
    if f.ts_ms.saturating_sub(lv.birth_ms) < min_age_ms {
        return false;
    }
    let (holds, strength_e2) = arm_inputs();
    if !holds {
        return false;
    }
    lv.approach = Some(Approach {
        arm_ms: f.ts_ms,
        arm_dist_bps: gap_bps(gap, f.tick),
        size_at_arm: f.size_lots,
        best_own_tick: f.best_own_tick,
        best_opp_tick: f.best_opp_tick,
        flow_1h_lots: f.flow_1h_lots,
        strength_e2,
        depth_behind_lots: f.depth_behind_lots,
        frontrun_lots: f.frontrun_lots,
        stack_levels: 0,
    });
    true
}

        self.approach_scratch = scratch;
    }

    /// То же плюс записи подхода (F1) в `approaches`. Порядок выдачи
    /// детерминирован: снятия по касанию и уходу цены — в порядке кадра,
    /// затем снятия смертью уровня — в порядке `(сторона, тик)` вместе с его
    /// смертью (перед записью оборванного смертью касания).
    pub fn observe_frame_with_approaches(
        &mut self,
        ts_ms: i64,
        side: Side,
        levels: &[LevelObs],
        out: &mut Vec<LevelRecord>,
        touches: &mut Vec<TouchRecord>,
        approaches: &mut Vec<ApproachRecord>,
    ) {
        self.cleanup_births(ts_ms);
        let ctx = self.begin_frame(ts_ms, side, levels);
        let carry_open_s = self.carry_open[ctx.s as usize];
        // Фазы кадра (W4в) — свободные функции над непересекающимися полями,
        // а не один вложенный метод: каждая берёт только то состояние, что
        // реально трогает, вызовы идут строго по очереди, поэтому ни одна
        // пара заимствований не пересекается во времени.
        scan_levels(
            &ctx,
            ts_ms,
            levels,
            &self.strength_ok,
            &self.strength_prefix,
            &mut self.live,
            &mut self.births,
            &mut self.carry,
            carry_open_s,
            &mut self.newborns,
            &mut self.touched,
            &mut self.armed,
            approaches,
        );
        close_carry_after_first_frame(&mut self.carry, &mut self.carry_open, ctx.s);
        detect_sweep(&self.live, &mut self.sweep, ctx.s, ctx.frame);
        compute_touch_stacks(&self.live, &mut self.touched, ctx.s, ctx.frame, ctx.mode);
        compute_arm_stacks(&mut self.live, &self.armed, ctx.s, ctx.frame, ctx.mode);
        resolve_deaths(
            &mut self.live,
            &mut self.sweep,
            &self.newborns,
            &self.touched,
            ts_ms,
            ctx.frame,
            ctx.warm_end,
            out,
            touches,
            approaches,
        );
        finalize_surviving_touches(
            &mut self.live,
            &mut self.touched,
            ts_ms,
            ctx.frame,
            ctx.warm_end,
            touches,
        );
    }

    /// Разбор кадра до прохода по наблюдениям (W4в, фаза 1): всё, что не
    /// зависит от конкретного наблюдения, — оборот за час, счётчик кадра,
    /// окно прогрева, флаги силы «×соседи», лучшие цены сторон.
    fn begin_frame(&mut self, ts_ms: i64, side: Side, levels: &[LevelObs]) -> FrameCtx {
        // Оборот за час к этому кадру — один раз на кадр, для касаний, начавшихся в нём.
        let flow_1h = self.flow_1h_lots(ts_ms);
        if self.start_ms.is_none() {
            self.start_ms = Some(ts_ms);
        }
        self.frame += 1;
        let frame = self.frame;
        let mode = self.cfg.mode;
        let window = self.cfg.repeat_window_ms;
        // Граница прогрева: рождения строго раньше не эмитируются — ни
        // смертью, ни касанием, ни подходом (индексы при этом растут).
        let warm_end = self
            .start_ms
            .unwrap_or(ts_ms)
            .saturating_add(self.effective_warmup_ms());
        strength_flags(
            mode,
            levels,
            &mut self.strength_ok,
            &mut self.strength_prefix,
        );
        let s = side_key(side);
        // Лучшая цена этой стороны в этом кадре — и последняя известная лучшая
        // цена другой стороны: полосе подхода нужна именно чужая цена (F1).
        let best_own = levels.first().map(|o| o.tick);
        let best_opp = self.best_tick[1 - s as usize];
        self.best_tick[s as usize] = best_own;
        let approach_d = self.cfg.approach_bps;
        let approach_min_age_ms = self.cfg.approach_min_age_ms;
        self.newborns.clear();
        self.touched.clear();
        self.armed.clear();
        FrameCtx {
            s,
            frame,
            mode,
            window,
            warm_end,
            best_own,
            best_opp,
            approach_d,
            approach_min_age_ms,
            flow_1h,
        }
    }

    /// Периодическая чистка `births` по cutoff (W4а): без нового рождения на
    /// том же ключе очередь никогда больше не проходит через
    /// `count_prior_births`, и её устаревшие записи не тримятся сами — карта
    /// иначе растёт вечно на ценах, где рождение было один раз. Не чаще раза
    /// в `repeat_window_ms`: после целого окна прошлые записи гарантированно
    /// устарели у любого ключа, чаще обходить всю карту незачем. `retain`
    /// только сдвигает и режет — не аллоцирует и не растит ёмкость.
    fn cleanup_births(&mut self, ts_ms: i64) {
        let window = self.cfg.repeat_window_ms;
        let due = self
            .births_cleaned_ms
            .is_none_or(|last| ts_ms.saturating_sub(last) >= window);
        if !due {
            return;
        }
        self.births_cleaned_ms = Some(ts_ms);
        let cutoff = ts_ms - window;
        self.births.retain(|_, q| {
            while q.front().is_some_and(|&t| t <= cutoff) {
                q.pop_front();
            }
            !q.is_empty()
        });
    }

    /// Один трейд ленты. Находит живой уровень той стороны, которую трейд ест
    /// на этом тике, и добавляет объём — иначе молча пропускает. Блочные,
    /// нулевые и поданные раньше рождения не считаются. RPI-сделки идут в
    /// свой счётчик: они исполнились об невидимую заявку, а не об этот уровень
    /// (В-55), поэтому метку исхода не сдвигают. Поиск в карте кучу не
    /// трогает, внутри — одно целое сложение с насыщением.
    pub fn observe_trade(&mut self, tr: TradeHit) {
        if tr.block || tr.lots <= 0 {
            return;
        }
        // Оборот инструмента (сила «×поток»): все неблочные сделки, включая
        // RPI, — это то, что рынок реально проторговал.
        {
            let minute = tr.exch_ms.div_euclid(60_000);
            let slot = minute.rem_euclid(FLOW_WINDOW_MIN as i64) as usize;
            if self.flow_slot_min[slot] != minute {
                self.flow_slot_min[slot] = minute;
                self.flow_ring[slot] = 0;
            }
            self.flow_ring[slot] = self.flow_ring[slot].saturating_add(tr.lots);
        }
        let key = (u8::from(tr.aggressor_is_buy), tr.tick);
        if let Some(lv) = self.live.get_mut(&key) {
            if tr.exch_ms < lv.birth_ms {
                return;
            }
            if tr.rpi {
                lv.rpi = lv.rpi.saturating_add(tr.lots);
            } else {
                lv.traded = lv.traded.saturating_add(tr.lots);
                // Окно реакции (E4): объём в первые секунды идущего касания —
                // по метке исполнения относительно старта касания.
                if let Some(t) = &mut lv.touch {
                    let since_ms = tr.exch_ms.saturating_sub(t.start_ms);
                    for (k, w) in REACTION_WINDOWS_S.iter().enumerate() {
                        if since_ms >= 0 && since_ms < w.saturating_mul(1_000) {
                            t.traded_first_s[k] = t.traded_first_s[k].saturating_add(tr.lots);
                        }
                    }
                }
            }
        }
    }

    /// Прогрев, который реально действует на эмиссию: `floor` — всегда ноль
    /// (режим отладки, без прогрева по определению), `percentile` — как
    /// сконфигурировано. `cfg.warmup_ms` в режиме `floor` не читается.
    fn effective_warmup_ms(&self) -> i64 {
        match self.cfg.mode {
            H3Mode::Floor { .. }
            | H3Mode::Notional { .. }
            | H3Mode::Strength { .. }

/// живые уровни (касание, подход, история силы) и заводит новые рождения.
/// Берёт только поля, которые реально трогает, — карту живых, карту
/// рождений, перенос возраста и буферы новорождённых/касаний кадра.
#[allow(clippy::too_many_arguments)]
fn scan_levels(
    ctx: &FrameCtx,
    ts_ms: i64,
    levels: &[LevelObs],
    strength_ok: &[bool],
    strength_prefix: &[i64],
    live: &mut SortedVec<(u8, i64), Live>,
    births: &mut SortedVec<(u8, i64), VecDeque<i64>>,
    carry: &mut SortedVec<(u8, i64), i64>,
    carry_open_s: bool,
    newborns: &mut Vec<(u8, i64, i64)>,
    touched: &mut Vec<Touched>,
    armed: &mut Vec<(u8, i64)>,
    approaches: &mut Vec<ApproachRecord>,
) {
    let FrameCtx {
        s,
        frame,
        mode,
        window,
        warm_end,
        best_own,
        best_opp,
        approach_d,
        approach_min_age_ms,
        flow_1h,
    } = *ctx;

    // Сумма лотов строго лучше текущего наблюдения по цене — префикс
    // кадра до его индекса: на индексе 0 ноль, дальше копится. Рядом —
    // цена **ближайшего** уровня с ненулевым размером среди этих лучших
    // (B2): «первый фронтранer», на чью цену ставится вход от фронтрана.
    let mut better_lots: i64 = 0;
    let mut near_better_tick: Option<i64> = None;
    // Направленная глубина (T2, П-02, Г-07): сумма размеров всего кадра на
    // этой стороне, один раз до цикла — внутри цикла «позади наблюдения i»
    // это `total_lots − better_lots (строго лучше i) − ob.size_lots (сам i)`,
    // без повторного обхода `levels`. Ноль аллокаций — тот же счётчик, что
    // уже копится по кадру.
    let total_lots: i64 = levels
        .iter()
        .fold(0i64, |acc, o| acc.saturating_add(o.size_lots));
    // К1 (T-23): палец поиска в `live` — уровни кадра идут от лучшего наружу,
    // ключ следующего рядом с ответом прошлого; ответ тот же, что у двоичного.
    let mut finger = 0usize;
    for (i, ob) in levels.iter().enumerate() {
        let key = (s, ob.tick);
        let best = i == 0;
        let strong = strength_ok.get(i).copied().unwrap_or(true);
        // Позади наблюдения i — строго дальше от середины (В-45: кадр идёт
        // от лучшей цены вглубь), не включая сам уровень.
        let depth_behind_lots = total_lots
            .saturating_sub(better_lots)
            .saturating_sub(ob.size_lots);
        // Считается лениво и не больше раза на наблюдение (W4г): нужна и
        // новому касанию, и сигналу подхода того же кадра — раньше уровень,
        // ставший касанием при включённом подходе, платил за неё дважды.
        let mut strength_e2_window: Option<[i64; STRENGTH_WINDOWS_BPS.len()]> = None;
        let mut strength_e2_now = || -> [i64; STRENGTH_WINDOWS_BPS.len()] {
            *strength_e2_window.get_or_insert_with(|| {
                std::array::from_fn(|k| {
                    neighbour_strength_e2(levels, strength_prefix, i, STRENGTH_WINDOWS_BPS[k] * 100)
                })
            })
        };
        match live.get_mut_from(&mut finger, &key) {
            Some(lv) => {
                lv.seen_frame = frame;
                lv.seen_top50 = ob.in_top50;
                lv.seen_size = ob.size_lots;
                lv.seen_strong = strong;
                // Р9 (T-17): сила окна истории нужна только выборке (не чаще
                // `STRENGTH_SAMPLE_MS`) и старту касания — считается лениво,
                // не больше раза на наблюдение; функция чистая, значения те же.
                let mut now_e2_cell: Option<i64> = None;
                let mut now_e2 = || {
                    *now_e2_cell.get_or_insert_with(|| {
                        neighbour_strength_e2(
                            levels,
                            strength_prefix,
                            i,
                            STRENGTH_HIST_WINDOW_BPS_E2,
                        )
                    })
                };
                if lv.strength_sample_due(ts_ms) {
                    lv.observe_strength(ts_ms, now_e2());
                }
                if ob.size_lots < lv.prev && lv.first_decrease_ms.is_none() {
                    lv.first_decrease_ms = Some(ts_ms);
                }
                lv.prev = ob.size_lots;
                let max_before = lv.max;
                if ob.size_lots > lv.max {
                    lv.max = ob.size_lots;
                    lv.max_ms = ts_ms;
                }
                // Сметённое последним шагом — с последнего кадра до
                // касания: читается до того, как значение этого кадра
                // его перезапишет; фронтран — за секунду до касания по
                // слотам (В-45), после наблюдения этого кадра.
                let swept = lv.better_lots;
                lv.better_lots = better_lots;
                lv.observe_frontrun(ts_ms, better_lots, near_better_tick);
                let (frontrun, frontrun_tick) = lv.frontrun_before(ts_ms);
                // Касание — переход на лучшую цену уровня, жившего до
                // кадра (В-43): был не лучшим на последнем наблюдении и
                // родился раньше этой метки. Родившийся лучшей ценой (или
                // ставший ею в миллисекунду рождения) касается только
                // после ухода с лучшей цены и возврата.
                let arrives = best && !lv.was_best && lv.birth_ms < ts_ms;
                lv.was_best = best;
                match (&mut lv.touch, arrives, best) {
                    (None, true, _) => {
                        let now_e2 = now_e2();
                        lv.touch = Some(Touch {
                            start_ms: ts_ms,
                            start_frame: frame,
                            size_at: ob.size_lots,
                            size_max_before: max_before,
                            frontrun,
                            frontrun_tick,
                            swept,
                            window_ticks: stack_window_ticks(ob.tick),
                            traded_at_start: lv.traded,
                            stack: 0,
                            stack_next_tick: None,
                            traded_first_s: [0; REACTION_WINDOWS_S.len()],
                            flow_1h_lots: flow_1h,
                            end_pending: false,
                            strength_e2: strength_e2_now(),
                            strength_held_e2: std::array::from_fn(|k| {
                                lv.strength_held_e2(
                                    ts_ms,
                                    STRENGTH_HELD_WINDOWS_S[k] * 1_000,
                                    now_e2,
                                )
                            }),
                            repeat_count: lv.repeat,
                            depth_behind_lots,
                        });
                        touched.push(Touched {
                            key,
                            stack: 0,
                            stack_next_tick: None,
                        });
                    }
                    (Some(t), _, false) => {
                        // Конец, отложенный до свипа, разрешается в том же
                        // кадре — второго ожидающего конца не бывает.
                        debug_assert!(!t.end_pending);
                        t.end_pending = true;
                        touched.push(Touched {
                            key,
                            stack: 0,
                            stack_next_tick: None,
                        });
                    }
                    (None, false, _) | (Some(_), _, true) => {}
                }
                // Сигнал подхода (F1): взвод и снятие по кадру. Умерший в
                // этом кадре уровень не трогается — снятие смертью
                // эмитится свипом. При `approach_bps = None` блока нет
                // вовсе: ни состояния, ни записей.
                if let Some(d_bps) = approach_d {
                    let dying = !ob.in_top50 || below_fraction(ob.size_lots, lv.max);
                    if !dying {
                        if let Some(best_opp_tick) = best_opp {
                            // Р1: сила и порог — только если дойдёт до взвода.
                            let arm_inputs = || {
                                let strength_e2 = strength_e2_now();
                                let holds = mode
                                    .holds_at_size(ob.tick, ob.size_lots, &strength_e2)
                                    .unwrap_or(false);
                                (holds, strength_e2)
                            };
                            let armed_now = observe_approach(
                                lv,
                                (d_bps, approach_min_age_ms),
                                s,
                                arm_inputs,
                                ApproachFrame {
                                    ts_ms,
                                    tick: ob.tick,
                                    size_lots: ob.size_lots,
                                    best,
                                    best_own_tick: best_own.unwrap_or(ob.tick),
                                    best_opp_tick,
                                    flow_1h_lots: flow_1h,
                                    depth_behind_lots,
                                    frontrun_lots: frontrun,
                                },
                                lv.birth_ms >= warm_end || lv.carried,
                                approaches,
                            );
                            if armed_now {
                                armed.push(key);
                            }
                        }
                    }
                }
            }
            None => {
                if ob.in_top50 && strong && mode.passes_birth(ob.tick, ob.size_lots) {
                    let repeat = count_prior_births(births, key, ts_ms, window);
                    let carried_birth = if carry_open_s {
                        carry.remove(&key)
                    } else {
                        None
                    };
