        .split_once('.')
        .ok_or_else(|| anyhow::anyhow!("сила {s:?}: нет точки"))?;
    anyhow::ensure!(frac.len() == 2, "сила {s:?}: не два знака");
    let whole: i64 = whole.parse()?;
    let frac: i64 = frac.parse()?;
    Ok(whole * 100 + frac)
